contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Call sendTo as the owner (this contract deployed c)
    function run(address receiver, uint256 amount) public payable {
        require(receiver != address(0));
        require(amount > 0);

        uint256 beforeC = address(c).balance;
        uint256 beforeR = receiver.balance;

        bool reverted;
        c.sendTo(receiver, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterC = address(c).balance;
        uint256 afterR = receiver.balance;

        // If the call did not revert then c must have had at least `amount` and balances changed by exactly amount.
        assert(reverted || (beforeC >= amount && beforeC - afterC == amount && afterR - beforeR == amount));
    }

    receive() external payable {}
}

